import React, { useState } from 'react';
import { SLAAlert, SLASeverity } from '../../../models/SLAAlert';
import { Badge } from '../../common/Badge';
import { Button } from '../../common/Button';
import { CountdownTimer } from '../CountdownTimer';
import { formatDistanceToNow } from 'date-fns';
import { vi } from 'date-fns/locale';
import styles from './AlertCard.module.css';

interface AlertCardProps {
  alert: SLAAlert;
  onEscalate: (alert: SLAAlert) => void;
  onReassign: (alert: SLAAlert) => void;
}

const SEVERITY_BADGE: Record<SLASeverity, string> = {
  [SLASeverity.Breached]: 'danger',
  [SLASeverity.Danger]:   'warning',
  [SLASeverity.Warning]:  'info',
  [SLASeverity.Watch]:    'secondary',
};

const SEVERITY_LABEL: Record<SLASeverity, string> = {
  [SLASeverity.Breached]: 'Vi phạm SLA',
  [SLASeverity.Danger]:   'Nguy cơ cao',
  [SLASeverity.Warning]:  'Cảnh báo',
  [SLASeverity.Watch]:    'Theo dõi',
};

const TYPE_LABEL: Record<string, string> = {
  ticket: 'Phiếu yêu cầu',
  task:   'Công việc',
};

export const AlertCard: React.FC<AlertCardProps> = ({ alert, onEscalate, onReassign }) => {
  const [expanded, setExpanded] = useState(false);

  const severityClass = styles[`severity_${alert.severity}`] ?? '';

  return (
    <div
      className={`${styles.card} ${severityClass} ${expanded ? styles.expanded : ''}`}
      onClick={() => setExpanded((v) => !v)}
    >
      {/* ── Header — always visible ── */}
      <div className={styles.cardHeader}>
        <div className={styles.titleRow}>
          <h3 className={styles.title}>{alert.title}</h3>
          <Badge variant={SEVERITY_BADGE[alert.severity] as any}>
            {SEVERITY_LABEL[alert.severity]}
          </Badge>
        </div>
        <div className={styles.meta}>
          <span className={styles.relatedId}>{alert.relatedNumber}</span>
          <span className={styles.sep}>•</span>
          <span>{TYPE_LABEL[alert.type] ?? alert.type}</span>
          {alert.departmentName && (
            <>
              <span className={styles.sep}>•</span>
              <span>{alert.departmentName}</span>
            </>
          )}
          {alert.escalationLevel > 0 && (
            <>
              <span className={styles.sep}>•</span>
              <span className={styles.escalationBadge}>
                🔥 Leo thang ×{alert.escalationLevel}
              </span>
            </>
          )}
        </div>
      </div>

      {/* ── Body — assignee, countdown, timestamps ── */}
      <div className={styles.cardBody}>
        <div className={styles.infoRow}>
          <div className={styles.infoItem}>
            <span className={styles.infoLabel}>Người phụ trách</span>
            <span className={styles.infoValue}>{alert.assigneeName}</span>
          </div>
          <div className={styles.infoItem}>
            <span className={styles.infoLabel}>SLA còn lại</span>
            <CountdownTimer deadline={alert.slaDeadline} />
          </div>
        </div>

        <div className={styles.timestamps}>
          <span>
            Tạo{' '}
            {formatDistanceToNow(new Date(alert.createdAt), { addSuffix: true, locale: vi })}
          </span>
          <span className={styles.sep}>·</span>
          <span>
            Hoạt động cuối{' '}
            {formatDistanceToNow(new Date(alert.lastActivityAt), { addSuffix: true, locale: vi })}
          </span>
        </div>
      </div>

      {/* ── Action bar — slides in on click ── */}
      {expanded && (
        <div className={styles.cardActions} onClick={(e) => e.stopPropagation()}>
          <Button variant="primary" size="sm" onClick={() => onEscalate(alert)}>
            <i className="fas fa-arrow-up" /> Leo thang
          </Button>
          <Button variant="warning" size="sm" onClick={() => onReassign(alert)}>
            <i className="fas fa-exchange-alt" /> Chuyển giao
          </Button>
        </div>
      )}
    </div>
  );
};
