/**
 * Real BFF API calls for Reports.
 *
 * Aggregates data in parallel from four existing endpoints:
 *   - GET /tickets    – ticket list for performance/compliance/workload metrics
 *   - GET /tasks      – task list for completion/workload metrics
 *   - GET /sla/stats  – SLA breach rate and overdue counts
 *   - GET /sla/alerts – overdue alert detail for compliance breach rows
 */

import type { ReportsData, ReportFilters } from '../../models/Report';
import { apiClient } from '../api';
import { type BffResponse, unwrap } from '../shared/bffEnvelope';
import type {
  BffTicketPagedForReport,
  BffTaskPagedForReport,
  BffSlaStatsForReport,
  BffSlaAlertsResponseForReport,
} from './responseModel';
import { mapBffToReportsData } from './mapper';

/** Max items to fetch per paginated call when computing aggregates. */
const AGGREGATE_PAGE_SIZE = 500;

export const reportsEndpoint = {
  getReportsData: async (filters: ReportFilters): Promise<ReportsData> => {
    // Build ticket query params (departmentId filter when provided)
    const ticketParams = new URLSearchParams({
      page:     '1',
      pageSize: String(AGGREGATE_PAGE_SIZE),
    });
    if (filters.department) ticketParams.set('departmentId', filters.department);

    // Build task query params
    const taskParams = new URLSearchParams({
      page:     '1',
      pageSize: String(AGGREGATE_PAGE_SIZE),
    });

    // Build SLA stats params
    const slaStatsParams = new URLSearchParams();
    if (filters.department) slaStatsParams.set('departmentId', filters.department);

    // Build SLA alerts params (fetch breached alerts for compliance detail)
    const slaAlertsParams = new URLSearchParams({
      page:     '1',
      pageSize: '200',
    });

    const [ticketsRes, tasksRes, slaStatsRes, slaAlertsRes] = await Promise.all([
      apiClient.get<BffResponse<BffTicketPagedForReport>>(
        `/tickets?${ticketParams}`,
      ),
      apiClient.get<BffResponse<BffTaskPagedForReport>>(
        `/tasks?${taskParams}`,
      ),
      apiClient.get<BffResponse<BffSlaStatsForReport>>(
        `/sla/stats${slaStatsParams.toString() ? `?${slaStatsParams}` : ''}`,
      ),
      apiClient.get<BffResponse<BffSlaAlertsResponseForReport>>(
        `/sla/alerts?${slaAlertsParams}`,
      ),
    ]);

    return mapBffToReportsData(
      unwrap(ticketsRes),
      unwrap(tasksRes),
      unwrap(slaStatsRes),
      unwrap(slaAlertsRes),
    );
  },
};
