import React from 'react';
import { Task } from '../../../../models/Task';
import { SubtaskState } from '../../types';
import { ChecklistItem } from './ChecklistItem';
import { AddSubtaskForm } from './AddSubtaskForm';
import styles from './ChecklistTab.module.css';

interface ChecklistTabProps {
  task: Task;
  editingSubtasks: Map<string, SubtaskState>;
  newSubtaskTitle: string;
  onToggleSubtask: (id: string) => Promise<void>;
  onAddSubtask: () => Promise<void>;
  onDeleteSubtask: (id: string) => Promise<void>;
  onStartEdit: (id: string, title: string) => void;
  onCancelEdit: (id: string) => void;
  onSaveEdit: (id: string) => Promise<void>;
  onEditTitleChange: (id: string, title: string) => void;
  onNewSubtaskChange: (title: string) => void;
  isProcessing?: boolean;
  // Auto-progress props
  autoProgressEnabled: boolean;
  showAutoProgressModal: boolean;
  onAutoProgressToggle: (enabled: boolean) => void;
  onDismissAutoProgressModal: (enable: boolean) => void;
}

export const ChecklistTab: React.FC<ChecklistTabProps> = ({
  task,
  editingSubtasks,
  newSubtaskTitle,
  onToggleSubtask,
  onAddSubtask,
  onDeleteSubtask,
  onStartEdit,
  onCancelEdit,
  onSaveEdit,
  onEditTitleChange,
  onNewSubtaskChange,
  isProcessing = false,
  autoProgressEnabled,
  showAutoProgressModal,
  onAutoProgressToggle,
  onDismissAutoProgressModal,
}) => {
  const completedCount = task.subtasks?.filter((st) => st.completed).length || 0;
  const totalCount = task.subtasks?.length || 0;

  return (
    <div className={styles.cardBody}>
      <div className={styles.section}>
        {/* Section header with auto-progress toggle */}
        <div className={styles.sectionHeader}>
          <div className={styles.sectionTitle}>
            <i className="fas fa-tasks"></i> Checklist ({completedCount}/{totalCount} completed)
          </div>
          <label className={styles.autoProgressToggle} title="Tự động cập nhật tiến độ dựa trên checklist">
            <input
              type="checkbox"
              checked={autoProgressEnabled}
              onChange={(e) => onAutoProgressToggle(e.target.checked)}
              className={styles.autoProgressCheckbox}
            />
            <span className={styles.autoProgressLabel}>
              <i className="fas fa-magic"></i> Tự động tiến độ
            </span>
          </label>
        </div>

        {autoProgressEnabled && (
          <div className={styles.autoProgressHint}>
            <i className="fas fa-info-circle"></i>
            Tiến độ tự động cập nhật khi hoàn thành checklist. Slider tiến độ bị vô hiệu hoá.
          </div>
        )}

        <div className={styles.checklist}>
          {/* Existing subtasks */}
          {task.subtasks && task.subtasks.length > 0 ? (
            task.subtasks.map((subtask) => {
              const editState = editingSubtasks.get(subtask.id);
              const isEditing = editState?.isEditing || false;

              return (
                <ChecklistItem
                  key={subtask.id}
                  subtask={subtask}
                  isEditing={isEditing}
                  editTitle={editState?.title}
                  onToggle={() => onToggleSubtask(subtask.id)}
                  onStartEdit={() => onStartEdit(subtask.id, subtask.title)}
                  onCancelEdit={() => onCancelEdit(subtask.id)}
                  onSaveEdit={() => onSaveEdit(subtask.id)}
                  onDelete={() => onDeleteSubtask(subtask.id)}
                  onEditTitleChange={(title) => onEditTitleChange(subtask.id, title)}
                  disabled={isProcessing}
                />
              );
            })
          ) : (
            <div className={styles.emptyChecklist}>
              <i className="fas fa-tasks"></i>
              <p>Chưa có subtask nào. Thêm mới để bắt đầu!</p>
            </div>
          )}

          {/* Add new subtask form */}
          <AddSubtaskForm
            value={newSubtaskTitle}
            onChange={onNewSubtaskChange}
            onAdd={onAddSubtask}
            disabled={isProcessing}
          />
        </div>
      </div>

      {/* First-use confirmation modal */}
      {showAutoProgressModal && (
        <div className={styles.modalOverlay}>
          <div className={styles.modal}>
            <div className={styles.modalIcon}>
              <i className="fas fa-magic"></i>
            </div>
            <h3 className={styles.modalTitle}>Cài đặt Tự động Tiến độ</h3>
            <p className={styles.modalBody}>
              Bạn có muốn tiến độ task tự động cập nhật theo checklist không?<br />
              Mỗi mục hoàn thành sẽ cộng thêm{' '}
              <strong>{totalCount > 0 ? Math.round(100 / (totalCount + 1)) : '...'} %</strong>{' '}
              vào tiến độ.
            </p>
            <div className={styles.modalActions}>
              <button
                className={styles.modalBtnSecondary}
                onClick={() => onDismissAutoProgressModal(false)}
              >
                Không, tự cập nhật
              </button>
              <button
                className={styles.modalBtnPrimary}
                onClick={() => onDismissAutoProgressModal(true)}
              >
                <i className="fas fa-magic"></i> Bật tự động
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};


