/**
 * TaskCompletionReport Component
 * Displays task completion metrics and trends
 */

import React from 'react';
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  BarElement,
  Tooltip,
  Legend,
} from 'chart.js';
import { Bar } from 'react-chartjs-2';
import type { TaskCompletionMetrics } from '../../../models/Report';
import styles from './TaskCompletionReport.module.css';

ChartJS.register(CategoryScale, LinearScale, BarElement, Tooltip, Legend);

interface TaskCompletionReportProps {
  data: TaskCompletionMetrics;
}

export const TaskCompletionReport: React.FC<TaskCompletionReportProps> = ({
  data,
}) => {
  const chartData = {
    labels: data.trend.map((point) => point.label),
    datasets: [
      {
        label: 'Hoàn thành',
        data: data.trend.map((point) => point.value),
        backgroundColor: '#10b981',
      },
    ],
  };

  const chartOptions = {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: {
        display: true,
        position: 'bottom' as const,
      },
    },
    scales: {
      y: {
        beginAtZero: true,
      },
    },
  };

  return (
    <div className={styles.reportCard}>
      <div className={styles.cardHeader}>
        <h3 className={styles.cardTitle}>
          <i className="fas fa-check-square"></i>
          Hoàn Thành Công Việc
        </h3>
        <button className={styles.exportButton}>
          <i className="fas fa-download"></i>
        </button>
      </div>
      <div className={styles.cardBody}>
        <div className={styles.statsGrid}>
          <div className={`${styles.statCard} ${styles.indigo}`}>
            <div className={styles.statLabel}>Tổng tasks</div>
            <div className={styles.statValue}>{data.totalTasks}</div>
          </div>
          <div className={`${styles.statCard} ${styles.green}`}>
            <div className={styles.statLabel}>Hoàn thành</div>
            <div className={styles.statValue}>{data.completedTasks}</div>
          </div>
          <div className={`${styles.statCard} ${styles.red}`}>
            <div className={styles.statLabel}>Quá hạn</div>
            <div className={styles.statValue}>{data.overdueTasks}</div>
          </div>
          <div className={`${styles.statCard} ${styles.teal}`}>
            <div className={styles.statLabel}>Tỷ lệ đúng hạn</div>
            <div className={styles.statValue}>{data.onTimeRate}%</div>
          </div>
        </div>
        <div className={styles.chartContainer}>
          <Bar data={chartData} options={chartOptions} />
        </div>
      </div>
    </div>
  );
};
