import React from 'react';
import { Ticket } from '../../../models/Ticket';
import { Card } from '../../../components/common/Card';
import { formatSLATime } from '../../../components/common/SLABadge';
import styles from './TicketSidebar.module.css';

interface TicketSidebarProps {
  ticket: Ticket;
}

const TicketSidebar: React.FC<TicketSidebarProps> = ({ ticket }) => {
  const slaTime = formatSLATime(ticket.sla.remainingMinutes);
  const slaProgress = 100 - ticket.sla.percentage;

  const getSLAColor = () => {
    if (ticket.sla.breached) return 'var(--danger-color)';
    if (ticket.sla.percentage < 10) return 'var(--danger-color)';
    if (ticket.sla.percentage < 25) return 'var(--warning-color)';
    return 'var(--success-color)';
  };

  const formatDateTime = (date: Date | string) => {
    const d = typeof date === 'string' ? new Date(date) : date;
    return d.toLocaleString('vi-VN', {
      month: 'short',
      day: 'numeric',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
    });
  };

  const getAvatarInitials = (name: string) => {
    return name
      .split(' ')
      .map((n) => n[0])
      .join('')
      .toUpperCase()
      .substring(0, 2);
  };

  return (
    <div className={styles.container}>
      {/* SLA Card */}
      <Card>
        <div className={styles.cardHeader}>
          <h3 className={styles.sidebarTitle}>
            <i className="fas fa-clock"></i>
            Trạng thái SLA
          </h3>
        </div>
        <div className={styles.cardBody}>
          <div className={styles.slaContent}>
            <div className={styles.slaTime} style={{ color: getSLAColor() }}>
              {slaTime}
            </div>
            <div className={styles.slaLabel}>Thời gian còn lại</div>
            <div className={styles.progressBar}>
              <div
                className={styles.progressFill}
                style={{
                  width: `${slaProgress}%`,
                  backgroundColor: getSLAColor(),
                }}
              />
            </div>
            <div className={styles.progressLabels}>
              <span>0%</span>
              <span>100%</span>
            </div>
          </div>
        </div>
      </Card>

      {/* Details Card */}
      <Card>
        <div className={styles.cardHeader}>
          <h3 className={styles.sidebarTitle}>
            <i className="fas fa-info-circle"></i>
            Details
          </h3>
        </div>
        <div className={styles.cardBody}>
          <div className={styles.details}>
            <div className={styles.detailItem}>
              <div className={styles.detailLabel}>Người tạo</div>
              <div className={styles.detailValue}>
                <div className={`${styles.avatar} ${styles.avatarSmall}`} style={{ backgroundColor: 'var(--green-500)' }}>
                  {getAvatarInitials(ticket.createdByName)}
                </div>
                <span>{ticket.createdByName}</span>
              </div>
            </div>

            <div className={styles.detailItem}>
              <div className={styles.detailLabel}>Người xử lý</div>
              <div className={styles.detailValue}>
                {ticket.assigneeName ? (
                  <>
                    <div className={`${styles.avatar} ${styles.avatarSmall}`} style={{ backgroundColor: 'var(--blue-500)' }}>
                      {getAvatarInitials(ticket.assigneeName)}
                    </div>
                    <span>{ticket.assigneeName}</span>
                  </>
                ) : (
                  <span className={styles.unassigned}>Chưa gán</span>
                )}
              </div>
            </div>

            <div className={styles.divider}></div>

            <div className={styles.detailItem}>
              <div className={styles.detailLabel}>Ngày tạo</div>
              <div className={styles.detailValueText}>{formatDateTime(ticket.createdAt)}</div>
            </div>

            <div className={styles.detailItem}>
              <div className={styles.detailLabel}>Cập nhật lần cuối</div>
              <div className={styles.detailValueText}>{formatDateTime(ticket.updatedAt)}</div>
            </div>

            <div className={styles.detailItem}>
              <div className={styles.detailLabel}>Hạn SLA</div>
              <div className={styles.detailValueText} style={{ color: getSLAColor(), fontWeight: 600 }}>
                {formatDateTime(ticket.sla.targetDate)}
              </div>
            </div>
          </div>
        </div>
      </Card>

      {/* Helpers Card — only rendered when support has been assigned */}
      {ticket.helpers && ticket.helpers.length > 0 && (
        <Card>
          <div className={styles.cardHeader}>
            <h3 className={styles.sidebarTitle}>
              <i className="fas fa-hands-helping"></i>
              Người Hỗ Trợ ({ticket.helpers.length})
            </h3>
          </div>
          <div className={styles.cardBody}>
            <div className={styles.details}>
              {ticket.helpers.map((h) => (
                <div key={h.id} className={styles.detailItem}>
                  <div className={styles.detailValue}>
                    <div
                      className={`${styles.avatar} ${styles.avatarSmall}`}
                      style={{ backgroundColor: 'var(--purple-500, #8b5cf6)' }}
                    >
                      {getAvatarInitials(h.userName)}
                    </div>
                    <div style={{ display: 'flex', flexDirection: 'column', gap: '2px' }}>
                      <span>{h.userName}</span>
                      <span style={{ fontSize: '0.7rem', color: 'var(--text-secondary)' }}>
                        Giao bởi {h.assignedByName} · {formatDateTime(h.assignedAt)}
                      </span>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </Card>
      )}

      {/* Related Tickets Card */}
      <Card padding="none">
        <div className={styles.cardHeader}>
          <h3 className={styles.sidebarTitle}>
            <i className="fas fa-link"></i>
            Phiếu Yêu Cầu Liên Quan
          </h3>
        </div>
        <div className={styles.relatedList}>
          {/* TODO: Wire to BFF GET /tickets/{id}/related when endpoint is available */}
          <div className={styles.relatedItem} style={{ opacity: 0.5, justifyContent: 'center' }}>
            <span className={styles.relatedTitle}>Chưa có phiếu liên quan</span>
          </div>
        </div>
      </Card>
    </div>
  );
};

export default TicketSidebar;
